/* All approved RS vectors. Synthetic host fixtures; no retail data. */
#define STAGE5_TEST_NO_MAIN
#include "drive_stage5_test.c"
#include "drive_presentation.h"
static const char *g_dir="docs/cleanroom-driving-physics/render-sampling/test-vectors";
static int g_fail;
#include "test_json.h"
static void near(double a,double b){assert(isfinite(a)&&fabs(a-b)<2e-6);}
static void vector3(J *a,float v[3]){if(a)for(int k=0;k<3;k++)v[k]=a->kid[k]->num;}
static void basis(J *a,ResBasis *b){if(a){vector3(a->kid[0],b->forward);vector3(a->kid[1],b->lateral);vector3(a->kid[2],b->up);}}
static DrivePresentation load(J *a){DrivePresentation p={.valid=1,.axes={{1,0,0},{0,1,0},{0,0,1}}};if(!a)return p;vector3(jget(a,"origin"),p.origin);if(jget(a,"yaw"))p.axes=res_basis_level(jnum(a,"yaw",0));basis(jget(a,"basis"),&p.axes);for(int i=0;i<4;i++){J*h=jget(a,"hub_local"),*d=jget(a,"travel"),*s=jget(a,"spin"),*r=jget(a,"steer");if(h)vector3(h->kid[i],p.hub[i]);if(d)p.travel[i]=d->kid[i]->num;if(s)p.phase[i]=s->kid[i]->num;if(r)p.steer[i]=r->kid[i]->num;}return p;}
static void expected3(const float v[3],J *a){for(int k=0;k<3;k++)near(v[k],a->kid[k]->num);}
static void proper(const ResBasis *b){const float*a[3]={b->forward,b->lateral,b->up};for(int i=0;i<3;i++)for(int j=0;j<3;j++)assert(fabs(res_dot(a[i],a[j])-(i==j))<2e-5);for(int k=0;k<3;k++)assert(fabs(a[0][(k+1)%3]*a[1][(k+2)%3]-a[0][(k+2)%3]*a[1][(k+1)%3]-a[2][k])<2e-5);}
static void same(const DrivePresentation*a,const DrivePresentation*b){assert(!memcmp(a,b,sizeof *a));}
static void cadence(void){Trace a,b;contact_init(&a,10);BodyCar car={.inertia={.5f,1.5f,2},.yaw_scale=2};assert(!stage5_drive_body(&a.drive,&car,1,0,1));b=a;const float groups[4][3]={{0,.2f,.7f},{.1f,.9f,0},{0},{0,.5f,1}};const int counts[4]={3,2,0,3};DrivePresentation before=drive_presentation_capture(&b.drive);for(int n=0;n<4;n++){tick5(&a,.5f,.1f,0,NULL);tick5(&b,.5f,.1f,0,NULL);DrivePresentation after=drive_presentation_capture(&b.drive);Stage1Drive saved=b.drive;for(int k=0;k<counts[n];k++){DrivePresentation p=drive_presentation_mix(&before,&after,groups[n][k]);proper(&p.axes);assert(!memcmp(&saved,&b.drive,sizeof saved));}assert(!memcmp(&a.drive,&b.drive,sizeof a.drive));assert(!memcmp(a.p,b.p,sizeof a.p));before=after;}}
int main(void){J*root=jload("render-sampling.json"),*vs=jget(root,"vectors");assert(vs&&vs->n==15);for(int n=0;n<vs->n;n++){J*v=vs->kid[n];const char*id=jstrv(v,"id");DrivePresentation a=load(jget(v,"before")),b=load(jget(v,"after")),p;float t=jnum(v,"alpha",.5);
 if(!strcmp(id,"linear-motion")){J*alphas=jget(v,"alphas"),*xs=jget(v,"expected_origin_x");for(int k=0;k<alphas->n;k++){p=drive_presentation_mix(&a,&b,alphas->kid[k]->num);near(p.origin[0],xs->kid[k]->num);}}
 else if(!strcmp(id,"independent-wheel")){p=drive_presentation_mix(&a,&b,t);J*e=jget(v,"expected");for(int k=0;k<4;k++){near(p.travel[k],jget(e,"travel")->kid[k]->num);near(p.steer[k],jget(e,"steer")->kid[k]->num);near(p.phase[k],jget(e,"spin")->kid[k]->num);}}
 else if(!strcmp(id,"spin-wrap-and-fast-turn")||!strcmp(id,"wheel-physical-side-and-sense")){J*x=jget(v,"before_spin"),*y=jget(v,"after_spin_unwrapped");if(!y)y=jget(v,"after_spin");for(int i=0;i<4;i++){a.phase[i]=x->kid[i]->num;b.phase[i]=y->kid[i]->num;J*h=jget(v,"hub_local");if(h){vector3(h->kid[i],a.hub[i]);vector3(h->kid[i],b.hub[i]);}}p=drive_presentation_mix(&a,&b,t);J*e=jget(v,"expected_spin_unwrapped");if(!e)e=jget(v,"expected_spin");for(int i=0;i<4;i++){near(p.phase[i],e->kid[i]->num);J*r=jget(v,"expected_display_phase");if(r){double phase=p.phase[i]-2*M_PI*floor(p.phase[i]/(2*M_PI));near(phase,r->kid[i]->num);}J*sign=jget(v,"expected_side_dot_lateral_signs");if(sign)near(drive_presentation_side(&p,i),sign->kid[i]->num);}}
 else if(!strcmp(id,"quarter-yaw")||!strcmp(id,"yaw-label-wrap")){a.axes=res_basis_level(jnum(v,"before_yaw",0));b.axes=res_basis_level(jnum(v,"after_yaw",0));p=drive_presentation_mix(&a,&b,t);expected3(p.axes.forward,jget(v,"expected_forward"));expected3(p.axes.lateral,jget(v,"expected_lateral"));expected3(p.axes.up,jget(v,"expected_up"));for(int k=0;k<9;k++){double alpha=k/8.,delta=atan2(sin(jnum(v,"after_yaw",0)-jnum(v,"before_yaw",0)),cos(jnum(v,"after_yaw",0)-jnum(v,"before_yaw",0)));p=drive_presentation_mix(&a,&b,alpha);near(p.axes.forward[0],cos(jnum(v,"before_yaw",0)+alpha*delta));near(p.axes.forward[1],sin(jnum(v,"before_yaw",0)+alpha*delta));}}
 else if(!strcmp(id,"stationary")){a=load(jget(v,"snapshot"));J*x=jget(v,"alphas");for(int i=0;i<x->n;i++){p=drive_presentation_mix(&a,&a,x->kid[i]->num);same(&p,&a);}}
 else if(!strcmp(id,"basis-properties")){J*x=jget(v,"yaw_pairs");for(int i=0;i<x->n;i++){a.axes=res_basis_level(x->kid[i]->kid[0]->num);b.axes=res_basis_level(x->kid[i]->kid[1]->num);for(int k=0;k<101;k++){p=drive_presentation_mix(&a,&b,k/100.f);proper(&p.axes);}p=drive_presentation_mix(&a,&b,.5);double yaw=jget(v,"expected_midpoint_yaws")->kid[i]->num;near(p.axes.forward[0],cos(yaw));near(p.axes.forward[1],sin(yaw));}}
 else if(!strcmp(id,"reset-and-mode-switch")){b=load(jget(v,"new_snapshot"));J*events=jget(v,"events");for(int i=0;i<events->n;i++){DrivePresentationHistory h;drive_presentation_reset(&h,&b);for(int k=0;k<3;k++){p=drive_presentation_sample(&h,k*.5f,0);same(&p,&b);}}}
 else if(!strcmp(id,"zero-multiple-ticks")){J*origins=jget(v,"completed_tick_origins"),*schedule=jget(v,"render_schedule");for(int i=0;i<schedule->n;i++){J*r=schedule->kid[i];int last=jnum(r,"last_tick",1);a.origin[0]=origins->kid[last-1]->num;b.origin[0]=origins->kid[last]->num;p=drive_presentation_mix(&a,&b,jnum(r,"alpha",0));near(p.origin[0],jnum(r,"x",0));}}
 else if(!strcmp(id,"alpha-one-and-follow-mode")){a=load(jget(v,"player"));b=load(jget(v,"followed_actor"));p=drive_presentation_mix(&a,&b,1);expected3(p.origin,jget(v,"expected_camera_actor_origin"));expected3(p.axes.forward,jget(v,"expected_camera_actor_forward"));}
 else if(!strcmp(id,"hub-lamp-sampled-basis")){p=drive_presentation_mix(&a,&b,t);float world[3],local[3];for(int i=0;i<4;i++){drive_presentation_point(&p,p.hub[i],world);expected3(world,jget(v,"expected_world_hubs")->kid[i]);}vector3(jget(v,"lamp_local"),local);drive_presentation_point(&p,local,world);expected3(world,jget(v,"expected_world_lamp"));vector3(jget(v,"camera_target_offset_local"),local);drive_presentation_point(&p,local,world);expected3(world,jget(v,"expected_world_camera_target"));}
 else if(!strcmp(id,"tilted-and-half-turn-bases")){J*pairs=jget(v,"basis_pairs");for(int i=0;i<pairs->n;i++){basis(pairs->kid[i]->kid[0],&a.axes);basis(pairs->kid[i]->kid[1],&b.axes);for(int scale=64;scale<=512;scale*=2){DrivePresentation old=a;for(int k=0;k<=scale;k++){p=drive_presentation_mix(&a,&b,(float)k/scale);proper(&p.axes);DrivePresentation repeat=drive_presentation_mix(&a,&b,(float)k/scale);same(&repeat,&p);const float*x=(const float*)&p.axes,*y=(const float*)&old.axes;for(int j=0;j<9;j++)assert(fabs(x[j]-y[j])<7./scale);old=p;}}}}
 else if(!strcmp(id,"pause-snap-current")){DrivePresentationHistory h={a,b};J*events=jget(v,"events");for(int k=0;k<events->n;k++){p=drive_presentation_sample(&h,jnum(v,"input_alpha",0),1);same(&p,&b);}}
 else if(!strcmp(id,"read-only-cadence"))cadence();
 else assert(!"unhandled approved vector");printf("RS vector %s passed\n",id);
 }jfree(root);puts("All 15 approved render-sampling vectors passed");return 0;}
